#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <pthread.h>

#define HT_BITS 17
#define HT_SIZE (1 << HT_BITS)
#define HT_MASK (HT_SIZE - 1)
#define N_THREADS 4

typedef struct {
    uint64_t hash;
    uint32_t offset;
    uint32_t len;
    uint32_t count;
} Entry;

typedef struct {
    const uint8_t *buf;
    size_t start;
    size_t end;
    Entry *htable;
    uint32_t *used_idx;
    uint32_t n_used;
} WorkerArg;

static const uint8_t char_lower[256] = {
    ['a']='a',['b']='b',['c']='c',['d']='d',['e']='e',['f']='f',['g']='g',['h']='h',['i']='i',['j']='j',
    ['k']='k',['l']='l',['m']='m',['n']='n',['o']='o',['p']='p',['q']='q',['r']='r',['s']='s',['t']='t',
    ['u']='u',['v']='v',['w']='w',['x']='x',['y']='y',['z']='z',
    ['A']='a',['B']='b',['C']='c',['D']='d',['E']='e',['F']='f',['G']='g',['H']='h',['I']='i',['J']='j',
    ['K']='k',['L']='l',['M']='m',['N']='n',['O']='o',['P']='p',['Q']='q',['R']='r',['S']='s',['T']='t',
    ['U']='u',['V']='v',['W']='w',['X']='x',['Y']='y',['Z']='z'
};

static inline int eq_lower(const uint8_t *a, const uint8_t *b, uint32_t len) {
    for (uint32_t i = 0; i < len; i++) {
        if ((a[i] | 32) != (b[i] | 32)) return 0;
    }
    return 1;
}

static inline int cmp_lower(const uint8_t *a, uint32_t la, const uint8_t *b, uint32_t lb) {
    uint32_t m = la < lb ? la : lb;
    for (uint32_t i = 0; i < m; i++) {
        uint8_t ca = a[i] | 32;
        uint8_t cb = b[i] | 32;
        if (ca != cb) return (int)ca - (int)cb;
    }
    return (la < lb) ? -1 : (la > lb ? 1 : 0);
}

void *worker_fn(void *arg) {
    WorkerArg *w = (WorkerArg *)arg;
    const uint8_t *buf = w->buf;
    size_t i = w->start;
    size_t end = w->end;
    Entry *ht = w->htable;
    uint32_t *used = w->used_idx;
    uint32_t n_used = 0;

    while (i < end) {
        uint8_t lc = char_lower[buf[i]];
        if (!lc) { i++; continue; }
        uint32_t start = (uint32_t)i;
        uint64_t h = 14695981039346656037ULL;
        do {
            h = (h ^ lc) * 1099511628211ULL;
            i++;
            lc = char_lower[buf[i]];
        } while (lc);
        uint32_t len = (uint32_t)i - start;
        if (!h) h = 1;
        uint32_t slot = (uint32_t)((h ^ (h >> 32)) & HT_MASK);
        while (1) {
            Entry *e = &ht[slot];
            if (e->count == 0) {
                e->hash = h;
                e->offset = start;
                e->len = len;
                e->count = 1;
                used[n_used++] = slot;
                break;
            }
            if (e->hash == h && e->len == len && eq_lower(buf + e->offset, buf + start, len)) {
                e->count++;
                break;
            }
            slot = (slot + 1) & HT_MASK;
        }
    }
    w->n_used = n_used;
    return NULL;
}

void run_wf(void) {
    struct stat st;
    uint8_t *buf = NULL;
    size_t size = 0;
    int is_mmap = 0;

    if (fstat(0, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0) {
        size = st.st_size;
        void *p = mmap(NULL, size + 1, PROT_READ, MAP_PRIVATE, 0, 0);
        if (p != MAP_FAILED) {
            buf = (uint8_t *)p;
            is_mmap = 1;
        }
    }
    if (!buf) {
        size_t cap = 65536;
        buf = malloc(cap + 1);
        ssize_t n;
        while ((n = read(0, buf + size, cap - size)) > 0) {
            size += n;
            if (size == cap) {
                cap *= 2;
                buf = realloc(buf, cap + 1);
            }
        }
        buf[size] = 0;
    }

    int nt = (size >= 1000000) ? N_THREADS : 1;
    WorkerArg args[N_THREADS];
    pthread_t tids[N_THREADS];

    size_t chunk = size / nt;
    size_t cur = 0;
    for (int t = 0; t < nt; t++) {
        args[t].buf = buf;
        args[t].start = cur;
        size_t nxt = (t == nt - 1) ? size : cur + chunk;
        while (nxt < size && char_lower[buf[nxt]]) nxt++;
        args[t].end = nxt;
        cur = nxt;
        args[t].htable = calloc(HT_SIZE, sizeof(Entry));
        args[t].used_idx = malloc(HT_SIZE * sizeof(uint32_t));
        args[t].n_used = 0;
        if (t > 0) pthread_create(&tids[t], NULL, worker_fn, &args[t]);
    }
    worker_fn(&args[0]);
    for (int t = 1; t < nt; t++) {
        pthread_join(tids[t], NULL);
        Entry *ht0 = args[0].htable;
        Entry *htt = args[t].htable;
        for (uint32_t u = 0; u < args[t].n_used; u++) {
            Entry src = htt[args[t].used_idx[u]];
            uint32_t slot = (uint32_t)((src.hash ^ (src.hash >> 32)) & HT_MASK);
            while (1) {
                Entry *e = &ht0[slot];
                if (e->count == 0) {
                    *e = src;
                    args[0].used_idx[args[0].n_used++] = slot;
                    break;
                }
                if (e->hash == src.hash && e->len == src.len && eq_lower(buf + e->offset, buf + src.offset, src.len)) {
                    e->count += src.count;
                    break;
                }
                slot = (slot + 1) & HT_MASK;
            }
        }
        free(htt);
        free(args[t].used_idx);
    }

    Entry top[10];
    int n_top = 0;
    Entry *ht0 = args[0].htable;
    for (uint32_t u = 0; u < args[0].n_used; u++) {
        Entry e = ht0[args[0].used_idx[u]];
        if (n_top == 10 && e.count < top[9].count) continue;
        int pos = n_top;
        while (pos > 0) {
            Entry *prev = &top[pos - 1];
            int better = 0;
            if (e.count > prev->count) better = 1;
            else if (e.count == prev->count) {
                if (cmp_lower(buf + e.offset, e.len, buf + prev->offset, prev->len) < 0) better = 1;
