            if (pos < 10) top[pos] = *prev;
            pos--;
        }
        if (pos < 10) {
            top[pos] = e;
            if (n_top < 10) n_top++;
        }
    }

    char outbuf[4096];
    int outpos = 0;
    for (int k = 0; k < n_top; k++) {
        for (uint32_t j = 0; j < top[k].len; j++) {
            outbuf[outpos++] = buf[top[k].offset + j] | 32;
        }
        outpos += sprintf(outbuf + outpos, " %u\n", top[k].count);
    }
    write(1, outbuf, outpos);

    free(ht0);
    free(args[0].used_idx);
    if (is_mmap) munmap(buf, size + 1);
    else free(buf);
}
